"""Independent verification of a version-3 result against its epoch.

Checks every published requirement: assignment feasibility, exact objectives,
the circulation, the residual-potential optimality certificate and the
next-ratio infeasibility cut.
"""
import sys
from fractions import Fraction

sys.path.insert(0, '/workspace/vendor')
sys.path.insert(0, '/workspace/submission')

import testcnnonnx
import testrnnonnx
from probability import window_thresholds


def predict(model, features):
    if not features:
        return []
    labels = [0] * len(features)
    if model == 'cnn':
        return testcnnonnx.evaluate_model_single_pass(features, labels)
    return testrnnonnx.evaluate_model_single_pass(features, labels)


def geometry(case):
    S = len(case['slots']); J = len(case['windows'])
    F = len(case['flows']); G = len(case['groups'])
    nodes = {'R': 0, 'Z': 1}
    a = [2 + 3 * s for s in range(S)]
    b = [3 + 3 * s for s in range(S)]
    e = [4 + 3 * s for s in range(S)]
    w = [2 + 3 * S + j for j in range(J)]
    z = [2 + 3 * S + J + f for f in range(F)]
    h = [2 + 3 * S + J + F + g for g in range(G)]
    return dict(S=S, J=J, F=F, G=G, a=a, b=b, e=e, w=w, z=z, h=h,
                K=2 + 3 * S + J + F + G)


def protocol_arcs(case, values, lower, geom):
    S, J, F, G = geom['S'], geom['J'], geom['F'], geom['G']
    slots = case['slots']
    times = [s[0] for s in slots]
    R, Z = 0, 1
    a, b, e, w, z, h = geom['a'], geom['b'], geom['e'], geom['w'], geom['z'], geom['h']
    B, I = case['bucket']
    W = 1 + J * times[-1]
    arcs = []
    for s in range(S):
        arcs.append((R, a[s], 0, I if s == 0 else slots[s][2], 0))
        arcs.append((a[s], b[s], 0, B, 0))
        if s + 1 < S:
            arcs.append((b[s], a[s + 1], 0, B, 0))
        arcs.append((b[s], e[s], 0, slots[s][1], 0))
    for s in range(S):
        for j in range(J):
            window = case['windows'][j]
            if (window[5] < _ths[j] and window[1] <= times[s] <= window[2]):
                arcs.append((e[s], w[j], 0, 1, (times[s] - window[1]) - values[j] * W))
    for j in range(J):
        arcs.append((w[j], z[case['windows'][j][0]], 0, 1, 0))
    for f in range(F):
        group = case['flows'][f][2]
        head = Z if group == -1 else h[group]
        arcs.append((z[f], head, lower[f], case['flows'][f][1], 0))
    for g in range(G):
        parent = case['groups'][g][0]
        head = Z if parent == -1 else h[parent]
        arcs.append((h[g], head, 0, case['groups'][g][1], 0))
    arcs.append((Z, R, 0, J, 0))
    return arcs


_ths = None


def check(case, result):
    """Return a list of violation strings (empty means the result is valid)."""
    global _ths
    errors = []
    geom = geometry(case)
    S, J, F, G = geom['S'], geom['J'], geom['F'], geom['G']
    slots = case['slots']
    times = [s[0] for s in slots]
    windows = case['windows']
    flows = case['flows']
    groups = case['groups']

    preds = predict(case['model'], [w[7] for w in windows])
    _ths = window_thresholds(case['stats'], windows)
    values = [windows[j][6] * case['class_values'][preds[j]] for j in range(J)]
    W = 1 + J * times[-1]

    if result['predictions'] != [int(p) for p in preds]:
        errors.append('predictions')
    if result['thresholds'] != [int(t) for t in _ths]:
        errors.append('thresholds')

    assignment = result['assignment']
    if len(assignment) != J:
        errors.append('assignment length')
        return errors

    # ---- assignment feasibility
    counts = [0] * F
    per_slot = [0] * S
    for j in range(J):
        slot = assignment[j]
        if slot == -1:
            continue
        if not (0 <= slot < S):
            errors.append('assignment slot range')
            return errors
        window = windows[j]
        if not (window[5] < _ths[j]):
            errors.append('window %d fails gate' % j)
        if not (window[1] <= times[slot] <= window[2]):
            errors.append('window %d outside window' % j)
        counts[window[0]] += 1
        per_slot[slot] += 1
    for s in range(S):
        if per_slot[s] > slots[s][1]:
            errors.append('slot %d capacity' % s)
    for f in range(F):
        if counts[f] > flows[f][1]:
            errors.append('flow %d ceiling' % f)
        if counts[f] < 0:
            errors.append('flow %d negative')
    for g in range(G):
        total = 0
        stack = [g]
        seen = set()
        while stack:
            node = stack.pop()
            if node in seen:
                continue
            seen.add(node)
            for f in range(F):
                if flows[f][2] == node:
                    total += counts[f]
            for g2 in range(G):
                if groups[g2][0] == node:
                    stack.append(g2)
        if total > groups[g][1]:
            errors.append('group %d ceiling' % g)
    # token dynamics
    B, I = case['bucket']
    carry = I
    for s in range(S):
        if s == 0:
            available = I
        else:
            available = min(B, carry + slots[s][2])
        if per_slot[s] > available:
            errors.append('slot %d tokens' % s)
        carry = available - per_slot[s]

    # ---- objectives
    utility = 0
    age = 0
    for j in range(J):
        if assignment[j] >= 0:
            utility += values[j]
            age += times[assignment[j]] - windows[j][1]
    if result['utility'] != utility:
        errors.append('utility %r != %r' % (result['utility'], utility))
    if result['age'] != age:
        errors.append('age %r != %r' % (result['age'], age))
    ratio = Fraction(1)
    for f in range(F):
        value = Fraction(counts[f], flows[f][0])
        if value < ratio:
            ratio = value
    p, q = result['ratio']
    if Fraction(p, q) != ratio:
        errors.append('ratio %r != %r' % (result['ratio'], ratio)
    if not (0 <= p <= q <= 64 and q >= 1):
        errors.append('ratio bounds')

    # ---- circulation
    lower = [0] * F
    for f in range(F):
        need = ratio * flows[f][0]
        lower[f] = -((-need.numerator) // need.denominator)
    arcs = protocol_arcs(case, values, lower, geom)
    if len(result['flow']) != len(arcs):
        errors.append('flow length %d != %d' % (len(result['flow']), len(arcs)))
        return errors
    net = {}
    for (u, v, l, h, c), x in zip(arcs, result['flow']):
        if not (l <= x <= h):
            errors.append('arc %d->%d flow %d outside [%d,%d]' % (u, v, x, l, h))
        net[u] = net.get(u, 0) - x
        net[v] = net.get(v, 0) + x
    for node, balance in net.items():
        if balance != 0:
            errors.append('conservation at node %d: %d' % (node, balance))
    # pair arcs agree with the assignment
    index = 0
    for s in range(S):
        index += 3 if s + 1 < S else 3
    # recompute the pair arc block position
    offset = 4 * S - 1  # slot arcs: 4 per slot except last has 3
    pos = 0
    arc_list = []
    for s in range(S):
        arc_list.append(('R_a', s))
        arc_list.append(('a_b', s))
        if s + 1 < S:
            arc_list.append(('b_a', s))
        arc_list.append(('b_e', s))
    for s in range(S):
        for j in range(J):
            window = windows[j]
            if window[5] < _ths[j] and window[1] <= times[s] <= window[2]:
                arc_list.append(('pair', s, j))
    for j in range(J):
        arc_list.append(('w_z', j))
    for f in range(F):
        arc_list.append(('z_out', f))
    for g in range(G):
        arc_list.append(('h_out', g))
    arc_list.append(('Z_R',))
    if len(arc_list) != len(arcs):
        errors.append('arc list mismatch')
    for kind, data in zip(arc_list, zip(arcs, result['flow'])):
        if kind[0] == 'pair':
            s, j = kind[1], kind[2]
            want = 1 if assignment[j] == s else 0
            if data[1] != want:
                errors.append('pair arc (%d,%d) flow %d != %d' % (s, j, data[1], want))

    # ---- potentials
    pot = result['potential']
    if len(pot) != geom['K']:
        errors.append('potential length')
        return errors
    for value in pot:
        if abs(value) > 10 ** 60:
            errors.append('potential magnitude')
    for (u, v, l, h, c), x in zip(arcs, result['flow']):
        if x < h and c + pot[u] - pot[v] < 0:
            errors.append('potential forward arc %d->%d' % (u, v))
        if x > l and -c + pot[v] - pot[u] < 0:
            errors.append('potential backward arc %d->%d' % (u, v))

    # ---- cut
    if ratio >= 1:
        if result['cut'] is not None:
            errors.append('cut must be null at full coverage')
    else:
        cands = set()
        for f in range(F):
            for k in range(flows[f][0] + 1):
                cands.add(Fraction(k, flows[f][0]))
        cands = sorted(cands)
        nxt = None
        for value in cands:
            if value > ratio:
                nxt = value
                break
        if nxt is None:
            errors.append('no next ratio')
        else:
            lower2 = [0] * F
            for f in range(F):
                need = nxt * flows[f][0]
                lower2[f] = -((-need.numerator) // need.denominator)
            arcs2 = protocol_arcs(case, values, lower2, geom)
            cut = result['cut']
            if cut is None:
                errors.append('cut missing')
            else:
                if len(set(cut)) != len(cut):
                    errors.append('cut duplicates')
                if any(not (0 <= node < geom['K']) for node in cut):
                    errors.append('cut node range')
                inside = set(cut)
                entering = 0
                leaving = 0
                for (u, v, l, h, c) in arcs2:
                    if u not in inside and v in inside:
                        entering += l
                    if u in inside and v not in inside:
                        leaving += h
                if not entering > leaving:
                    errors.append('cut not infeasible: %d <= %d' % (entering, leaving))
    return errors


def check_reports(case, result, errors):
    """Cross-check the reports against the protocol semantics independently."""
    import metrics
    report = metrics.selected_report(case['flows'], case['windows'],
                                    result['predictions'], result['assignment'])
    got = result['reports']
    for level in ('packet', 'stream'):
        for key in ('accuracy', 'macro_precision', 'macro_recall', 'macro_f1'):
            if abs(got[level][key] - report[level][key]) > 1e-12:
                errors.append('report %s %s' % (level, key))
        if got[level]['confusion'] != report[level]['confusion']:
            errors.append('report %s confusion' % level)
    return errors
